(globalThis.webpackChunkeduxio=globalThis.webpackChunkeduxio||[]).push([[229],{2499(e,t,a){e.exports={src:{srcSet:a.p+"assets/ideal-img/how-google-uses-data-to-build-a-better-worker.6ceac1e.640.png 640w,"+a.p+"assets/ideal-img/how-google-uses-data-to-build-a-better-worker.850705b.1030.png 1030w",images:[{path:a.p+"assets/ideal-img/how-google-uses-data-to-build-a-better-worker.6ceac1e.640.png",width:640,height:360},{path:a.p+"assets/ideal-img/how-google-uses-data-to-build-a-better-worker.850705b.1030.png",width:1030,height:579}],src:a.p+"assets/ideal-img/how-google-uses-data-to-build-a-better-worker.6ceac1e.640.png",toString:function(){return a.p+"assets/ideal-img/how-google-uses-data-to-build-a-better-worker.6ceac1e.640.png"},placeholder:void 0,width:640,height:360},preSrc:"data:image/png;base64,"}},9772(e,t,a){"use strict";a.r(t),a.d(t,{assets:()=>c,contentTitle:()=>d,default:()=>u,frontMatter:()=>h,metadata:()=>o,toc:()=>p});const o=JSON.parse('{"id":"how-google-uses-data-to-build-a-better-worker","title":"How Google Uses Data to Build a Better Worker","description":"For the search and advertising juggernaut, human resources is more than human","source":"@site/docs/how-google-uses-data-to-build-a-better-worker.mdx","sourceDirName":".","slug":"/how-google-uses-data-to-build-a-better-worker","permalink":"/library/how-google-uses-data-to-build-a-better-worker","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"title":"How Google Uses Data to Build a Better Worker","pagination_prev":null,"pagination_next":null}}');var s=a(4848),n=a(8453),i=a(547),r=a(2499),l=a.n(r);const h={title:"How Google Uses Data to Build a Better Worker",pagination_prev:null,pagination_next:null},d=void 0,c={},p=[{value:"Better-Than-Human Relations",id:"better-than-human-relations",level:2},{value:"What Google Learned",id:"what-google-learned",level:2},{value:"Where Does High Performance Come From?",id:"where-does-high-performance-come-from",level:2},{value:"About the Author",id:"about-the-author",level:3}];function m(e){const t={a:"a",em:"em",h2:"h2",h3:"h3",hr:"hr",li:"li",p:"p",ul:"ul",...(0,n.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(t.p,{children:(0,s.jsx)(t.em,{children:"For the search and advertising juggernaut, human resources is more than human"})}),"\n",(0,s.jsx)(t.p,{children:(0,s.jsxs)(t.em,{children:["By\xa0",(0,s.jsx)(t.a,{href:"https://www.theatlantic.com/author/chris-derose/",children:"Chris DeRose"}),", October 7, 2013, The Atlantic"]})}),"\n","\n",(0,s.jsx)(i.A,{img:l()}),"\n",(0,s.jsx)(t.hr,{}),"\n",(0,s.jsx)(t.p,{children:"\u201cI have charts and graphs to back me up. So f*** off.\u201d"}),"\n",(0,s.jsx)(t.p,{children:"Not the mantra you\u2019d expect from your typical human resources representative. But every new hire for Google\u2019s People Analytics department, part of the company\u2019s HR function (which it calls People Operations), gets a laptop sticker emblazoned with this slogan. More than just an attention getter, it succinctly captures the profound difference in how Google addresses all matters related to people. Googlers maintain a firm belief that insights from data can systematically improve performance and leadership within the company\u2019s ever-growing empire."}),"\n",(0,s.jsx)(t.p,{children:"While the rest of the world is waking up to analytics and the power of Big Data, Google has spent years methodically building one of the most refined performance-management engines in the corporate world.  Similar to any of the company\u2019s other departments, every People Operations project starts with a question to answer. Google\u2019s People Analytics team has posed questions that range from tactical issues (\u201cWhat if we could decrease ramp-up time for new employees by a month?\u201d) to the existential (\u201cWhat if all engineers were able to reach their potential for innovation?\u201d) to the seemingly outlandish (\u201cWhat if working at Google increased your life span by a year?\u201d). The questions lie at the heart of solving fundamental business problems related to managing the employee life cycle, maximizing employee\u2019s potential contribution, or improving Googlers\u2019 wellness."}),"\n",(0,s.jsx)(t.p,{children:"The impetus for the company\u2019s data-based approach to the generally subjective domain of people decisions came from Laszlo Bock, Google\u2019s SVP of People Operations. Bock, who joined the company in 2006 after stints with GE and McKinsey, found a like-minded ally when he hired Prasad Setty to run the company\u2019s analytics department.  At first glance, Setty is an unexpected HR leader with his chemical engineering degree and quick admission that he found the softer courses in his MBA curriculum frustrating because people decisions tend to invite temperamental, emotional and subjective choices. Bock challenged Setty to bring the same rigor to people decisions that Google applied to its engineering analysis."}),"\n",(0,s.jsx)(t.p,{children:"Recalling how Google once tested forty-two different color shades for the Google toolbar to determine which hue optimized click-through rates, Bock put a stake in the ground that has since differentiated Google\u2019s approach. As Setty recalled during our interview, Bock said plainly, \u201cWe need to be able to measure, to find out what does and doesn\u2019t work at Google rather than just adopt best practices.\u201d"}),"\n",(0,s.jsx)(t.h2,{id:"better-than-human-relations",children:"Better-Than-Human Relations"}),"\n",(0,s.jsx)(t.p,{children:"Over the past six years, Setty has built his People Analytics department into the company\u2019s mainframe. While Google won\u2019t disclose its exact size, estimates are that Setty has dozens of employees including PhDs, hardcore technologists and ex-consultants. As Setty told us, \u201cthe combined power of the group is having the business people make sure we\u2019re solving the right problems, the stats folks ensure there\u2019 s rigor in how we do it and the technologists who make the solutions scalable and transparent\u201d. The goal of People Analytics is to \u201ccomplement human decision makers, not replace them.\u201d"}),"\n",(0,s.jsx)(t.p,{children:"Tackling Bock\u2019s challenge, the team\u2019s mission statement is for \u201call people decisions at Google to be based on data and analytics.\u201d While many companies seek to make data-based talent decisions, Google deploys the kind of rigorous, scientific testing and statistical analysis that is more common in university labs. Running real experiments, according to Setty, helps describe \u201ca small but significant percentage of the variance in human behavior.\u201d"}),"\n",(0,s.jsx)(t.p,{children:"But Setty and his team learned early on while working on a project for Google\u2019s engineering department that leaders didn\u2019t want algorithms to replace human judgment. Rather than entrust important talent decisions to black-box calculations, Google\u2019s leaders asked Setty to focus on providing insights that could help decision-makers improve the odds of getting complex decisions right. As Setty explained, the models that result from his department\u2019s experiments explain normal or \u201caverage contexts\u201d that won\u2019t apply universally. The goal of People Analytics is to \u201ccomplement human decision makers, not replace them.\u201d"}),"\n",(0,s.jsx)(t.h2,{id:"what-google-learned",children:"What Google Learned"}),"\n",(0,s.jsx)(t.p,{children:"Attracting, retaining and developing talent at Google is serious business, as the analytic team has demonstrated that exceptional technologists can have a performance differential of up to three hundred times an average employee.\xa0 Over the last half-dozen years, Setty\u2019s team has produced significant insights that have:"}),"\n",(0,s.jsxs)(t.ul,{children:["\n",(0,s.jsx)(t.li,{children:"helped limit the number of interviews required (company analysis showed that more than four interviewers didn\u2019t lead to higher quality hiring),"}),"\n",(0,s.jsx)(t.li,{children:"revealed the optimal organizational size and shape of various departments,"}),"\n",(0,s.jsx)(t.li,{children:"shown how to better manage maternity leave resulting in a fifty percent reduction in defections,"}),"\n",(0,s.jsx)(t.li,{children:"created on-boarding agenda for an employee\u2019s first four days of work that boosted productivity by up to 15 percent"}),"\n",(0,s.jsx)(t.li,{children:"and produced an algorithm to review rejected applications (Google gets over two million applications every year) that has helped the company hire some talented engineers its screening process would have otherwise missed."}),"\n"]}),"\n",(0,s.jsxs)(t.p,{children:["While the company keeps much of its analysis confidential, one of the high profile cases it shared was dubbed \u201cProject Oxygen.\u201d First reported in the New York Times, as an\xa0",(0,s.jsx)(t.a,{href:"https://www.google.com/url?sa=t&rct=j&q=&esrc=s&source=web&cd=1&ved=0CC4QFjAA&url=http%3A%2F%2Fwww.nytimes.com%2F2011%2F03%2F13%2Fbusiness%2F13hire.html%3Fpagewanted%3Dall&ei=7-FSUtPAOovm8gS4yYHoBQ&usg=AFQjCNEQ5Uu0LG06AiKGSt80L2_0qwr9bw&sig2=IuYMtF_VUn4a9KC73LtmAw&bvm=bv.53537100,d.eWU",children:"\u201c8-point plan to help managers improve,\u201d"}),"\xa0the list of leadership characteristics indicative of Google\u2019s high performers is less remarkable than how the analysis by Setty\u2019s team has since influenced people policies and processes at the company. Even Bock was initially unimpressed when he saw the list, which included management altruisms such as \u201chave a clear vision\u201d or \u201chelp your employees with career development.\u201d"]}),"\n",(0,s.jsx)(t.p,{children:"But Bock\u2019s imperative to make people issues data-based was prescient and, for the first time, the study created belief among Google\u2019s highly technical employee base that leadership actually makes a difference in their world. (In its early days, Google famously eliminated all management positions declaring them unnecessary. The failed experiment didn\u2019t last long.)"}),"\n",(0,s.jsx)(t.p,{children:"Since then, the analytics team has worked with other parts of People Operations and the business leaders to make the eight leadership behaviors the basis for twice annual manager feedback surveys; they\u2019re probed further in the annual organization survey and are the criteria for the \u201cGreat Manager Award.\u201d Winners who are named great managers share a weeklong trip with their significant other and Google senior leaders. Rather than award cash or prizes, Setty says Google gives employees what they want most \u2014 time and exposure to other leaders. Setty explains that analysis of the company\u2019s annual survey, Googlegeist, demonstrates that Googlers prize opportunities to exchange ideas with senior leaders, and this interaction can have more of an impact on career satisfaction than the pace of their promotions."}),"\n",(0,s.jsx)(t.h2,{id:"where-does-high-performance-come-from",children:"Where Does High Performance Come From?"}),"\n",(0,s.jsx)(t.p,{children:"Setty\u2019s team is far from finished and has continued to expand its scope. The next big project will focus on what makes a high-performing team at Google. The fundamental questions the company is trying to answer include the ideal number and type of people on a team and how team dynamics impact output. These aren\u2019t new questions, and there\u2019s decades of academic literature that Setty\u2019s team will reference in its analysis. What makes Google\u2019s approach so different is that it\u2019s unwilling to stop there and simply rely on past research, conventional wisdom or industry best practice. The team is looking for unique insight into how these factors predict success at Google."}),"\n",(0,s.jsx)(t.p,{children:"Ultimately, Setty\u2019s team is looked upon as a valued business partner because it brings hard data that can help leaders better manage the human dynamic. And it\u2019s not simply about productivity, but also about keeping the unique aspects of Google\u2019s culture that makes it such a desirable place to work.\xa0 After all, as Setty\u2019s team has proven, when employees are happier they perform better and stay longer."}),"\n",(0,s.jsx)(t.hr,{}),"\n",(0,s.jsx)(t.h3,{id:"about-the-author",children:"About the Author"}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.a,{href:"https://www.theatlantic.com/author/chris-derose/",children:"Chris DeRose"})," is a\xa0workforce-management consultant\xa0and\xa0the\xa0co-author of\xa0",(0,s.jsx)(t.a,{href:"http://www.leadershipnow.com/leadershop/9781591843887.html",children:"Judgment on the Front Line: How Smart Companies Win by Trusting Their People"}),"."]})]})}function u(e={}){const{wrapper:t}={...(0,n.R)(),...e.components};return t?(0,s.jsx)(t,{...e,children:(0,s.jsx)(m,{...e})}):m(e)}}}]);